import{_ as r,o as t,c as a,ae as o}from"./chunks/framework.D9_ZvfG7.js";const k=JSON.parse('{"title":"关于我","description":"","frontmatter":{"title":"关于我","date":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"blog/2026-08-01-guan-yu-wo.md","filePath":"blog/2026-08-01-guan-yu-wo.md"}'),s={name:"blog/2026-08-01-guan-yu-wo.md"};function l(i,e,n,p,g,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="关于我" tabindex="-1">关于我 <a class="header-anchor" href="#关于我" aria-label="Permalink to &quot;关于我&quot;">​</a></h1><p>我是 Lxyao，一个扎根 Android 底层的内核折腾爱好者。设备是真我 GT5 Pro，骁龙 8 Gen 3（SM8650）平台，日常在 KernelSU、APatch、Magisk、LSPosed 这些 root 与隐藏框架之间反复横跳。</p><h2 id="在内核这件事上" tabindex="-1">在内核这件事上 <a class="header-anchor" href="#在内核这件事上" aria-label="Permalink to &quot;在内核这件事上&quot;">​</a></h2><p>我维护着 <a href="https://github.com/Lxyao077/oppo_oplus_realme_sm8650" target="_blank" rel="noreferrer">oppo_oplus_realme_sm8650</a> 内核编译仓库，这是从上游 cctv18 fork 出来的一套自动化构建脚本，覆盖 6.1.57 到 6.1.141 共 7 个内核版本，支持 ReSukiSU、SUSFS、KPM、Droidspaces、BBR 等模块的可选编译。每次上游更新或者自己想加新东西，就是改 YAML、推 CI、等 artifact、刷进去看能不能开机——这个循环已经跑了无数遍。</p><p>还有 <a href="https://github.com/Lxyao077/GKI_KernelSU_SUSFS" target="_blank" rel="noreferrer">GKI_KernelSU_SUSFS</a>，一套覆盖 5.10 到 6.12 全版本的 GKI 内核自动构建仓库，内置 ReSukiSU + SUSFS，带 BBG 基带守护、Droidspaces 容器、Re-Kernel 等可选功能。做这个的初衷很简单：不想每次换内核版本都要重新配一遍。</p><h2 id="搞过的模块和框架" tabindex="-1">搞过的模块和框架 <a class="header-anchor" href="#搞过的模块和框架" aria-label="Permalink to &quot;搞过的模块和框架&quot;">​</a></h2><ul><li><p><strong><a href="https://github.com/Lxyao077/vector-fork" target="_blank" rel="noreferrer">Vector Fork</a></strong>：LSPosed 框架的复苏分支。折腾过它的 daemon/app 架构、AIDL 接口层、CI 签名问题。LSPosed 停更之后，这个 fork 是少数还能在 Android 14/15 上跑起来的选择。我参与过维护和 UI 适配。</p></li><li><p><strong><a href="https://github.com/Lxyao077/TieJia" target="_blank" rel="noreferrer">TieJia</a></strong>：一套 Play Integrity 强过检模块。TEESimulator + PlayIntegrityFork 的组合拳，目标是让解锁的设备也能通过 Strong Integrity。</p></li><li><p><strong><a href="https://github.com/Lxyao077/specter" target="_blank" rel="noreferrer">Specter</a></strong>：统一的 Play Integrity 和 root 隐藏方案。研究过它的冲突检测机制、Zygisk 实现自动识别、hotinstall 免重启更新等设计模式。</p></li><li><p><strong><a href="https://github.com/Lxyao077/ReZygisk" target="_blank" rel="noreferrer">ReZygisk</a></strong>：透明的 Zygisk 实现。和 YukiZygisk 一样，都属于内核级注入方案，比传统的 ptrace 注入更干净。</p></li><li><p><strong><a href="https://github.com/Lxyao077/YukiSU" target="_blank" rel="noreferrer">YukiSU</a> / <a href="https://github.com/Lxyao077/YukiZygisk" target="_blank" rel="noreferrer">YukiZygisk</a></strong>：内核级 root 和 Zygisk 的新探索。关注的是如何在 KSU/APatch 之外找到更灵活的内核 hook 路径。</p></li><li><p><strong><a href="https://github.com/Lxyao077/susfs4ksu-module" target="_blank" rel="noreferrer">susfs4ksu-module</a></strong>：KernelSU 的增强隐藏模块。SUSFS 是内核态文件系统级别的挂载隐藏，配合这个模块可以在用户态做更细粒度的控制。</p></li><li><p><strong><a href="https://github.com/Lxyao077/LSPosed-Irena" target="_blank" rel="noreferrer">LSPosed-Irena</a></strong>：另一个 LSPosed 的 fork 分支。虽然命名自嘲&quot;useless&quot;，但任何一个能跑起来的 LSPosed 分支在这个社区里都弥足珍贵。</p></li><li><p><strong><a href="https://github.com/Lxyao077/ksu_toolkit" target="_blank" rel="noreferrer">ksu_toolkit</a></strong>：KernelSU 的调试工具箱。日常用来排查模块冲突、验证签名、测试新特性。</p></li></ul><h2 id="关于这篇文章" tabindex="-1">关于这篇文章 <a class="header-anchor" href="#关于这篇文章" aria-label="Permalink to &quot;关于这篇文章&quot;">​</a></h2><p>没有宏大叙事，就是记录一下自己到底折腾了什么。内核这件事上，我还在学，上面的项目大部分是站在巨人肩膀上的 fork 和维护，算不上&quot;开发&quot;。但每一步——修一个 CI 报错、改一行 defconfig、绕过一次检测——都是真实的。</p><p>如果这些对你有用，欢迎 Star，也欢迎提 Issue 交流。</p><p>GitHub: <a href="https://github.com/Lxyao077" target="_blank" rel="noreferrer">@Lxyao</a></p>',11)])])}const c=r(s,[["render",l]]);export{k as __pageData,c as default};
